import{c as t,Q as o,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Context Window Management","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-autoload-en/context-management.md","filePath":"research/reports/2026-06-06-autoload-en/context-management.md","lastUpdated":1780842316000}'),r={name:"research/reports/2026-06-06-autoload-en/context-management.md"};function a(s,e,c,l,d,m){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="context-window-management" tabindex="-1">Context Window Management <a class="header-anchor" href="#context-window-management" aria-label="Permalink to &quot;Context Window Management&quot;">​</a></h1><h2 id="prompt-caching-core-principles-static-first" tabindex="-1">Prompt Caching Core Principles (Static First) <a class="header-anchor" href="#prompt-caching-core-principles-static-first" aria-label="Permalink to &quot;Prompt Caching Core Principles (Static First)&quot;">​</a></h2><ul><li>CLAUDE.md content = most stable cache prefix, always placed first, never moved. block-level <code>&lt;!-- --&gt;</code> injection stripped before injecting = zero-token maintenance notes.</li><li><strong>Mid-session prohibited</strong>: ① switching models ② adding/removing tools ③ modifying CLAUDE.md → wait until session ends.</li><li><strong>NLAH principle</strong>: Right context &gt; more context. A precise hint injected at the correct position can reduce 95% of tokens; context should be at HEAD (original goal) or TAIL (latest tool output); middle layer holds dynamic state, avoid static descriptions there.</li></ul><h2 id="compact-hint" tabindex="-1">Compact hint <a class="header-anchor" href="#compact-hint" aria-label="Permalink to &quot;Compact hint&quot;">​</a></h2><p><code>/compact preserve: task goal, most recent tool results (incl. full file path and error string verbatim, do not rewrite), safety red lines, conventions, Traditional Chinese output; discard: intermediate step details, superseded exploration paths</code></p><ul><li><strong>Post-compact self-check</strong> (see refs/post-compact-checklist.md): ① Is the task goal still present? ② Are safety red lines still present? ③ Are the most recent tool results undistorted? Any failure → <code>/rewind</code>.</li></ul><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li><code>/usage</code> to view real-time session token/cost.</li><li><strong>Cache health metrics</strong> (see refs/cache-health-metrics.md): <code>cache_hit_rate = cache_read / input_tokens</code>, long-running sessions should be &gt; 0.7; sudden drop → first check if model/tool/CLAUDE.md was changed mid-session (four major cache-breaking sources). Dynamic information injected via <code>&lt;system-reminder&gt;</code>, do not write into CLAUDE.md prefix.</li><li><strong>Hard Token Budget</strong> (cross-cutting discipline: prevent loop runaway): <ul><li>Per-task budget: <strong>4,000 tokens</strong> (single task limit)</li><li>Per-session budget: <strong>30,000 tokens</strong> (entire session limit)</li><li>Action: approaching budget → <code>/compact &lt;hint&gt;</code>; exceeded → <code>/clear</code> to start new session</li></ul></li><li><strong>Compact triggers</strong> (priority: behavioral signal &gt; numeric threshold): <ol><li><strong>Behavioral signal</strong>: Model produces &quot;please provide more context&quot; / &quot;what do you want to do?&quot; lost-questions → immediately <code>/rewind</code> or <code>/compact</code></li><li><strong>Numeric threshold</strong>: general tasks <strong>70%</strong>; beginners ~<strong>60%</strong>; long agentic <strong>30–35%</strong> proactive compact</li></ol></li><li><code>/compact &lt;hint&gt;</code> to continue task; <code>/clear</code> to switch tasks.</li><li><strong>PreCompact hook</strong>: <code>exit 2</code> can completely block compact (protect important uncommitted decisions).</li></ul>',8)])])}const h=t(r,[["render",a]]);export{p as __pageData,h as default};
